patch:
diff --git a/app/client/dynamic_window_vertical.cpp b/app/client/dynamic_window_vertical.cpp
index e57c8363..48433d2e 100644
--- a/app/client/dynamic_window_vertical.cpp
+++ b/app/client/dynamic_window_vertical.cpp
@@ -98,13 +98,13 @@ void DynamicWindowVerticalClass::Clear_Flags(unsigned int flags)
 		Invalidate();
 	}
 }
-// NOT EXACT: the client stores the cleared flags, reloads them and ORs in the new bits; this form folds both into one store
+
 void DynamicWindowVerticalClass::Set_Alignment(unsigned int flags)
 {
 	unsigned int old_flags = Flags;
 	Flags &= ~0xF0;
-	Flags |= flags & 0xF0;
-	if (Flags != old_flags) {
+	unsigned int new_flags = Or_Flags(Flags, flags & 0xF0);
+	if (new_flags != old_flags) {
 		Invalidate();
 	}
 }
